/* 作文优质句型（分类） */
const EN_SENTENCES = [{"cat":"图画描述","en":"As is vividly depicted in the drawing above, ______, which conveys a thought-provoking message.","zh":"正如上图生动描绘的那样，……，这传递了一个发人深省的信息。"},{"cat":"图画描述","en":"What is clearly presented in the cartoon is that ______, while the caption reads \"______\".","zh":"漫画清晰呈现的是……，配文写道\"……\"。"},{"cat":"图画描述","en":"The picture, simple as it is, conveys a profound implication concerning ______.","zh":"这幅图虽简单，却传达了关于……的深刻寓意。"},{"cat":"现象引入","en":"In recent years, ______ has become an increasingly conspicuous phenomenon in contemporary society.","zh":"近年来，……已成为当代社会日益显著的现象。"},{"cat":"现象引入","en":"There is no denying that ______ has aroused widespread public concern.","zh":"不可否认，……已引起公众广泛关注。"},{"cat":"原因分析","en":"The reasons behind this phenomenon are manifold, among which the most prominent is that ______.","zh":"这一现象背后原因众多，其中最突出的是……。"},{"cat":"原因分析","en":"This can be attributed to a combination of factors, ranging from ______ to ______.","zh":"这可归因于多重因素，从……到……。"},{"cat":"原因分析","en":"A case in point is that ______, which vividly illustrates the point mentioned above.","zh":"一个恰当的例子是……，它生动说明了上述观点。"},{"cat":"影响论述","en":"Such a tendency, if left unchecked, will inevitably undermine ______.","zh":"这种趋势如果不加以控制，必将损害……。"},{"cat":"影响论述","en":"It exerts a far-reaching influence not only on individuals but also on society as a whole.","zh":"它不仅对个人，而且对整个社会产生深远影响。"},{"cat":"影响论述","en":"The benefits it brings about far outweigh the drawbacks it may entail.","zh":"它带来的益处远远超过可能引发的弊端。"},{"cat":"让步转折","en":"Admittedly, ______; nevertheless, this by no means suggests that ______.","zh":"诚然，……；然而，这绝不意味着……。"},{"cat":"让步转折","en":"While it is true that ______, we should not overlook the fact that ______.","zh":"虽然……确实如此，但我们不应忽视……这一事实。"},{"cat":"对策建议","en":"It is high time that effective measures were taken to address this issue.","zh":"现在是采取有效措施解决这一问题的时候了。（虚拟语气）"},{"cat":"对策建议","en":"Concerted efforts should be made by the government, schools and individuals alike.","zh":"政府、学校和个人都应共同努力。"},{"cat":"对策建议","en":"Only in this way can we expect a promising future in this respect.","zh":"只有这样，我们才能期待在这方面有光明的未来。（倒装）"},{"cat":"结尾升华","en":"In conclusion, it is the responsibility of every one of us to ______.","zh":"总之，……是我们每个人的责任。"},{"cat":"结尾升华","en":"Only when we ______ can we truly ______ and thus embrace a brighter tomorrow.","zh":"只有当我们……，才能真正……，从而拥抱更光明的明天。"},{"cat":"结尾升华","en":"To sum up, what the drawing conveys is far beyond the picture itself; it mirrors ______.","zh":"总而言之，图画所传达的远超图画本身，它折射出……。"},{"cat":"万能亮点","en":"It is universally acknowledged that perseverance is the mother of success.","zh":"众所周知，坚持是成功之母。"},{"cat":"万能亮点","en":"Rather than complaining about the darkness, we would be better off lighting a candle.","zh":"与其抱怨黑暗，不如点亮一支蜡烛。"},{"cat":"万能亮点","en":"No one can achieve success overnight; it is the accumulation of daily efforts that counts.","zh":"没有人能一夜成功，日积月累的努力才是关键。"},{"cat":"图画描述","en":"From the perspective of the cartoon, we can clearly observe that ______, which serves as a mirror of social reality.","zh":"从漫画的角度看，我们可以清楚地看到……，它是社会现实的一面镜子。"},{"cat":"现象引入","en":"Nowadays, there is a growing concern over ______, which has sparked a heated debate among the public.","zh":"如今，人们对……日益关注，这在公众中引发了激烈讨论。"},{"cat":"现象引入","en":"With the rapid development of society, ______ has gradually found its way into every corner of our life.","zh":"随着社会的快速发展，……已逐渐渗透到我们生活的每个角落。"},{"cat":"原因分析","en":"Several factors could account for this phenomenon, with the following ones being the most critical.","zh":"若干因素可解释这一现象，其中以下几点最为关键。"},{"cat":"原因分析","en":"The root cause lies in the fact that ______, which has long been overlooked.","zh":"根本原因在于……，这一点长期被忽视。"},{"cat":"影响论述","en":"If this trend continues, it will exert a detrimental impact on both individuals and the whole society.","zh":"若此趋势延续，将对个人乃至整个社会产生有害影响。"},{"cat":"影响论述","en":"From my perspective, this phenomenon is a double-edged sword that brings both opportunities and challenges.","zh":"在我看来，这一现象是把双刃剑，既带来机遇也带来挑战。"},{"cat":"让步转折","en":"Granted, there is some truth in the opposing view; nevertheless, we cannot turn a blind eye to the downside.","zh":"诚然，反方观点也有道理；然而，我们不能对弊端视而不见。"},{"cat":"对策建议","en":"It is imperative for the authorities to formulate relevant policies to regulate ______.","zh":"有关部门亟需制定相关政策来规范……。"},{"cat":"对策建议","en":"As college students, we should cultivate the awareness of ______ from an early age.","zh":"作为大学生，我们应从小培养……的意识。"},{"cat":"结尾升华","en":"Only by making joint efforts can we build a harmonious society where everyone thrives.","zh":"唯有共同努力，我们才能建成一个人人都能茁壮成长的和谐社会。"},{"cat":"结尾升华","en":"I firmly believe that a brighter future is within our reach if we take action now.","zh":"我坚信，只要我们现在行动起来，更光明的未来就触手可及。"},{"cat":"万能亮点","en":"There is a growing recognition that ______ plays an indispensable role in personal growth.","zh":"人们日益认识到，……在个人成长中起着不可或缺的作用。"},{"cat":"万能亮点","en":"As the proverb goes, \"______\", which still holds true in today's world.","zh":"正如谚语所说：\"……\"，这在当今社会依然成立。"}];;

/* 长难句解析 */
const EN_LONG_SENTENCES = [
  {
    en: 'It is not obvious how the capacity to visualize objects and to figure out numerical patterns suits one to answer questions that have eluded some of the best poets and philosophers.',
    src: '2015年英语一 阅读 Text 3 同源句式',
    zh: '想象物体和找出数字规律的能力如何使一个人能够回答那些让一些最杰出的诗人和哲学家都困惑的问题，这一点并不明显。',
    key: '主干 It is not obvious how...（形式主语 + how 引导主语从句）；that have eluded... 为定语从句修饰 questions。'
  },
  {
    en: 'The changes identified by David Graddol all present clear and major challenges to the UK\u2019s providers of English language teaching to people of other countries and to broader education business sectors.',
    src: '2017年英语一 翻译 Part C',
    zh: 'David Graddol 所指出的这些变化，都给英国向其他国家民众提供英语教学的机构以及更广泛的教育产业带来了明确而重大的挑战。',
    key: '主语 The changes 后接过去分词短语作后置定语；present A to B and to C 双宾结构。'
  },
  {
    en: 'Those societies that fail to adapt to a rapidly changing environment are, in the long run, doomed to decline, however powerful they may appear at present.',
    src: '经典高分句式（让步状语从句 + 定语从句）',
    zh: '那些无法适应快速变化环境的社会，从长远看注定衰落，无论它们当下看起来多么强大。',
    key: 'however + adj. + 主谓 = 无论多么……；that 引导定语从句修饰 Those societies。'
  },
  {
    en: 'What is at issue here is not whether technology should be embraced, but the extent to which it should be allowed to reshape human relationships.',
    src: '经典高分句式（表语从句 + not...but 结构）',
    zh: '此处争论的焦点不是是否应当拥抱技术，而是应在多大程度上允许它重塑人际关系。',
    key: 'What 引导主语从句；the extent to which 为"介词 + which"定语从句，写作可直接套用。'
  },
  {
    en: 'Not until we recognize the value of daily accumulation will we truly appreciate why small, consistent efforts eventually lead to remarkable achievements.',
    src: '经典高分句式（完全倒装）',
    zh: '直到我们认识到日积月累的价值，才会真正理解为什么微小而持续的努力最终会带来非凡成就。',
    key: 'Not until 置于句首引起部分倒装（will we），是作文提分的高频句式。'
  },
  {
    en: 'Given that resources are inherently limited, the question of how to allocate them efficiently has long been at the heart of economic debate.',
    src: '经典高分句式（Given that 状语从句）',
    zh: '鉴于资源本质上是有限的，如何有效分配资源的问题长期以来一直是经济学争论的核心。',
    key: 'Given that = Considering that，写作中替代 Because 的高级表达。'
  }
];

