/* 新增：EN_READINGS */
const EN_READINGS = [{"year":2019,"text":"Text 1","src":"2019 考研英语一 阅读理解 Text 1","title":"英国“薪酬追回”新规与企业短期主义","passage":"Financial regulators in Britain have imposed a rather unusual rule on the bosses of big banks. Starting next year, any guaranteed bonus of top executives could be delayed 10 years if their banks are under investigation for wrongdoing. The main purpose of this “clawback” rule is to hold bankers accountable for harmful risk-taking and to restore public trust in financial institutions. Yet officials also hope for a much larger benefit: more long-term decision-making not only by banks but by all corporations, to build a stronger economy for future generations.\n“Short-termism,” or the desire for quick profits, has worsened in publicly traded companies, says the Bank of England's top economist, Andrew Haldane. He quotes a giant of classical economics, Alfred Marshall, in describing this financial impatience as acting like “children who pick the plums out of their pudding to eat them at once” rather than putting them aside to be eaten last.\nThe average time for holding a stock in both the United States and Britain, he notes, has dropped from seven years to seven months in recent decades. Transient investors, who demand high quarterly profits from companies, can hinder a firm's efforts to invest in long-term research or to build up customer loyalty. This has been dubbed “quarterly capitalism.”\nIn addition, new digital technologies have allowed more rapid trading of equities, quicker use of information, and thus shortens attention spans in financial markets. “There seems to be a predominance of short-term thinking at the expense of long-term investing,” said Commissioner Daniel Gallagher of the US Securities and Exchange Commission in a speech this week.\nIn the US, the Sarbanes-Oxley Act of 2002 has pushed most public companies to defer performance bonuses for senior executives by about a year, slightly helping reduce “short-termism.” In its latest survey of CEO pay, The Wall Street Journal finds that “a substantial part” of executive pay is now tied to performance.\nMuch more could be done to encourage “long-termism,” such as changes in the tax code and quicker disclosure of stock acquisitions. In France, shareholders who hold onto a company investment for at least two years can sometimes earn more voting rights in a company.\nWithin companies, the right compensation design can provide incentives for executives to think beyond their own time at the company and on behalf of all stakeholders. Britain's new rule is a reminder to bankers that society has an interest in their performance, not just for the short term but for the long term.","questions":[{"q":"According to Paragraph 1, one motive in imposing the new rule is to ______.","options":["A. enhance bankers' sense of responsibility","B. help corporations achieve larger profits","C. build a new system of financial regulation","D. guarantee the bonuses of top executives"],"k":0,"ans":"选 A。解析：细节题。第一段第三句指出该“clawback”规则的主要目的是 to hold bankers accountable for harmful risk-taking（让银行家为有害的冒险行为负责），A 项 enhance bankers' sense of responsibility 是其同义替换。B、C、D 在定位区间均无对应信息。"},{"q":"Alfred Marshall is quoted to indicate ______.","options":["A. the conditions for generating quick profits","B. governments' impatience in decision-making","C. the solid structure of publicly traded companies","D. “short-termism” in economic activities"],"k":3,"ans":"选 D。解析：例证题。引用出现在第二段，其论点句是“‘Short-termism,’ or the desire for quick profits, has worsened in publicly traded companies”。马歇尔“把布丁里的李子挑出来马上吃掉的孩子”的比喻正是用来说明经济活动中的“短期主义”，故选 D。"},{"q":"It is argued that the influence of transient investment on public companies can be ______.","options":["A. indirect","B. adverse","C. minimal","D. temporary"],"k":1,"ans":"选 B。解析：细节题。第三段指出 Transient investors ... can hinder a firm's efforts to invest in long-term research or to build up customer loyalty（短期投资者会阻碍公司进行长期研究投资或培养客户忠诚度）。hinder 表明其影响是负面的，B 项 adverse（不利的）正确。"},{"q":"The US and France examples are used to illustrate ______.","options":["A. the obstacles to preventing “short-termism”","B. the significance of long-term thinking","C. the approaches to promoting “long-termism”","D. the prevalence of short-term thinking"],"k":2,"ans":"选 C。解析：例证题。第五、六段分别举美国《萨班斯—奥克斯利法案》推迟发放绩效奖金、法国长期持股者可获更多投票权的例子，两者都是鼓励“长期主义”的具体做法，故选 C。"},{"q":"Which of the following would be the best title for the text?","options":["A. Failure of Quarterly Capitalism","B. Patience as a Corporate Virtue","C. Decisiveness Required of Top Executives","D. Frustration of Risk-taking Bankers"],"k":1,"ans":"选 B。解析：主旨题。全文以英国“薪酬追回”新规切入，批评“短期主义”、倡导企业长期决策，末段再次强调社会关注的是长期表现。B 项“耐心是一种企业美德”准确概括全文主旨。"}]},{"year":2020,"text":"Text 1","src":"2020 考研英语一 阅读理解 Text 1","title":"英国“文化之镇”奖提议之辩","passage":"A group of Labour MPs, among them Yvette Cooper, are bringing in the new year with a call to institute a UK “town of culture” award. The proposal is that it should sit alongside the existing city of culture title, which was held by Hull in 2017 and has been awarded to Coventry for 2021. Cooper and her colleagues argue that the success of the crown for Hull, where it brought in £220m of investment and an avalanche of arts, ought not to be confined to cities. Britain's towns, it is true, are not prevented from applying, but they generally lack the resources to put together a bid to beat their bigger competitors. A town of culture award could, it is argued, become an annual event, attracting funding and creating jobs.\nSome might see the proposal as a booby prize for the fact that Britain is no longer able to apply for the much more prestigious title of European capital of culture, a sought-after award bagged by Glasgow in 1990 and Liverpool in 2008. A cynic might speculate that the UK is on the verge of disappearing into an endless fever of self-celebration in its desperation to reinvent itself for the post-Brexit world: after town of culture, who knows what will follow — village of culture? Suburb of culture? Hamlet of culture?\nIt is also wise to recall that such titles are not a cure-all. A badly run “year of culture” washes in and out of a place like the tide, bringing prominence for a spell but leaving no lasting benefits to the community. The really successful holders of such titles are those that do a great deal more than fill hotel bedrooms and bring in high-profile arts events and good press for a year. They transform the aspirations of the people who live there; they nudge the self-image of the city into a bolder and more optimistic light. It is hard to get right, and requires a remarkable degree of vision, as well as cooperation between city authorities, the private sector, community groups and cultural organisations. But it can be done: Glasgow's year as European capital of culture can certainly be seen as one of a complex series of factors that have turned the city into the powerhouse of art, music and theatre that it remains today.\nA “town of culture” could be not just about the arts but about honouring a town's peculiarities — helping sustain its high street, supporting local facilities and above all celebrating its people and turn it into action.","questions":[{"q":"Cooper and her colleagues argue that a “town of culture” award could ______.","options":["A. consolidate the town-city ties in Britain","B. promote cooperation among Britain's towns","C. increase the economic strength of Britain's towns","D. focus Britain's limited resources on cultural events"],"k":2,"ans":"选 C。解析：细节题。第一段末句指出 A town of culture award could ... become an annual event, attracting funding and creating jobs（吸引资金、创造就业），这正是提升城镇经济实力，故选 C。"},{"q":"According to Paragraph 2, the proposal might be regarded by some as ______.","options":["A. a sensible compromise","B. a self-deceiving attempt","C. an eye-catching bonus","D. an inaccessible target"],"k":1,"ans":"选 B。解析：推断题。第二段说有人视之为 booby prize（安慰奖），愤世嫉俗者更认为英国正陷入 an endless fever of self-celebration（无休止的自我庆祝狂热）。可见该提议被一些人看作自欺欺人之举，故选 B。"},{"q":"The author suggests that a title holder is successful only if it ______.","options":["A. endeavours to maintain its image","B. meets the aspirations of its people","C. brings its local arts to prominence","D. commits to its long-term growth"],"k":3,"ans":"选 D。解析：细节题。第三段先说糟糕的“文化年”leaving no lasting benefits to the community（不留下持久利益），随后指出真正成功者所做的远不止于一年的热闹，而是改变居民的抱负与城市自我形象，即着眼长期发展，故选 D。"},{"q":"Glasgow is mentioned in Paragraph 3 to present ______.","options":["A. a contrasting case","B. a supporting example","C. a background story","D. a related topic"],"k":1,"ans":"选 B。解析：例证题。第三段末以 But it can be done: Glasgow's year as European capital of culture ... 引出格拉斯哥，用以支持前文“做好这件事是可能的”这一观点，属于支撑性例证，故选 B。"},{"q":"What is the author's attitude towards the proposal?","options":["A. Skeptical","B. Objective","C. Favourable","D. Critical"],"k":2,"ans":"选 C。解析：态度题。作者虽指出此类头衔并非万灵药，但末段以肯定语气展望“文化之镇”可以彰显城镇特色、支持本地设施、赞美当地人民，整体持支持态度，故选 C（Favourable）。"}]},{"year":2021,"text":"Text 1","src":"2021 考研英语一 阅读理解 Text 1","title":"英国铁路票价年年上涨是否合理","passage":"How can the train operators possibly justify yet another increase to rail passenger fares? It has become a grimly reliable annual ritual: every January the cost of travelling by train rises, imposing a significant extra burden on those who have no option but to use the rail network to get to work or otherwise. This year's rise, an average of 2.7 per cent, may be a fraction lower than last year's, but it is still well above the official Consumer Price Index (CPI) measure of inflation.\nSuccessive governments have permitted such increases on the grounds that the cost of investing in and running the rail network should be borne by those who use it, rather than the general taxpayer. Why, the argument goes, should a car-driving pensioner from Lincolnshire have to subsidise the daily commute of a stockbroker from Surrey? Equally, there is a sense that the travails of commuters in the South East, many of whom will face among the biggest rises, have received too much attention compared to those who must endure the relatively poor infrastructure of the Midlands and the North.\nHowever, over the past 12 months, those commuters have also experienced some of the worst rail strikes in years. It is all very well train operators trumpeting the improvements they are making to the network, but passengers should be able to expect a basic level of service for the substantial sums they are now paying to travel. The responsibility for the latest wave of strikes rests on the unions. However, there is a strong case that those who have been worst affected by industrial action should receive compensation for the disruption they have suffered.\nThe Government has pledged to change the law to introduce a minimum service requirement so that, even when strikes occur, services can continue to operate. This should form part of a wider package of measures to address the long-running problems on Britain's railways. Yes, more investment is needed, but passengers will not be willing to pay more indefinitely if they must also endure cramped, unreliable services, punctuated by regular chaos when timetables are changed, or planned maintenance is managed incompetently. The threat of nationalisation may have been seen off for now, but it will return with a vengeance if the justified anger of passengers is not addressed in short order.","questions":[{"q":"The author holds that this year's increase in rail passenger fares ______.","options":["A. will ease train operators' burden","B. has kept pace with inflation","C. is a big surprise to commuters","D. remains an unreasonable measure"],"k":3,"ans":"选 D。解析：细节题。第一段以 grimly reliable annual ritual、a significant extra burden 表明作者的否定态度，并指出今年 2.7% 的涨幅 still well above the official CPI measure of inflation（仍远高于官方通胀水平），可见涨价并不合理，故选 D。"},{"q":"The stockbroker in Paragraph 2 is used to stand for ______.","options":["A. car drivers","B. rail travellers","C. local investors","D. ordinary taxpayers"],"k":1,"ans":"选 B。解析：例证题。第二段论点句为“铁路成本应由使用者承担，而非一般纳税人”。例句中开车的养老金领取者对应“一般纳税人”，而 stockbroker 的 daily commute 对应“使用铁路网的人”，故 stockbroker 指代铁路乘客，选 B。"},{"q":"It is indicated in Paragraph 3 that train operators ______.","options":["A. are offering compensation to commuters","B. are trying to repair relations with the unions","C. have failed to provide an adequate service","D. have suffered huge losses owing to the strikes"],"k":2,"ans":"选 C。解析：细节题。第三段第二句：It is all very well train operators trumpeting the improvements ... but passengers should be able to expect a basic level of service for the substantial sums they are now paying to travel。but 后为语义重点，说明乘客付了高价却未享受到基本服务，即运营商未能提供合格服务，故选 C。"},{"q":"If unable to calm down passengers, the railways may have to face ______.","options":["A. the loss of investment","B. the collapse of operations","C. a reduction of revenue","D. a change of ownership"],"k":3,"ans":"选 D。解析：细节题。末段末句：The threat of nationalisation ... will return with a vengeance if the justified anger of passengers is not addressed in short order。国有化（nationalisation）即所有权的变更，故选 D。"},{"q":"Which of the following would be the best title for the text?","options":["A. Who Are to Blame for the Strikes?","B. Constant Complaining Doesn't Work","C. Can Nationalisation Bring Hope?","D. Ever-Rising Fares Aren't Sustainable"],"k":3,"ans":"选 D。解析：主旨题。全文以票价年年上涨为议题，指出乘客付费与所得服务不匹配，并警告乘客不会无限期地承受涨价。D 项既点明主题（不断上涨的票价）又体现作者观点（不可持续），故选 D。"}]},{"year":2022,"text":"Text 1","src":"2022 考研英语一 阅读理解 Text 1","title":"博物馆里的塑料藏品保护难题","passage":"People often complain that plastics are too durable. Water bottles, shopping bags, and other trash litter the planet, from Mount Everest to the Mariana Trench, because plastics are everywhere and don't break down easily. But some plastic materials change over time. They crack and frizzle. They “weep” out additives. They melt into sludge. All of which creates huge headaches for institutions, such as museums, trying to preserve culturally important objects. The variety of plastic objects at risk is dizzying: early radios, avant-garde sculptures, celluloid animation stills from Disney films, the first artificial heart.\nCertain artifacts are especially vulnerable because some pioneers in plastic art didn't always know how to mix ingredients properly, says Thea van Oosten, a polymer chemist who, until retiring a few years ago, worked for decades at the Cultural Heritage Agency of the Netherlands. “It's like baking a cake: If you don't have exact amounts, it goes wrong,” she says. “The object you make is already a time bomb.”\nAnd sometimes, it's not the artist's fault. In the 1960s, the Italian artist Piero Gilardi began to create hundreds of bright, colorful foam pieces. Those pieces included small beds of roses and other items as well as a few dozen “nature carpets” — large rectangles decorated with foam pumpkins, cabbages, and watermelons. He wanted viewers to walk around on the carpets — which meant they had to be durable.\nUnfortunately, the polyurethane foam he used is inherently unstable. It's especially vulnerable to light damage, and by the mid-1990s, Gilardi's pumpkins, roses, and other figures were splitting and crumbling. Museums locked some of them away in the dark. So van Oosten and her colleagues worked to preserve Gilardi's sculptures. They infused some with stabilizing and consolidating chemicals. Van Oosten calls those chemicals “sunscreens” because their goal was to prevent further light damage and rebuild worn polymer fibers. She is proud that several sculptures have even gone on display again, albeit sometimes beneath protective cases.\nDespite success stories like van Oosten's, preservation of plastics will likely get harder. Old objects continue to deteriorate. Worse, biodegradable plastics designed to disintegrate, are increasingly common. And more is at stake here than individual objects. Joana Lia Ferreira, an assistant professor of conservation and restoration at the NOVA School of Science and Technology, notes that archaeologists first defined the great material ages of human history — Stone Age, Iron Age, and so on — after examining artifacts in museums. We now live in an age of plastic, she says, “and what we decide to collect today, what we decide to preserve ... will have a strong impact on how in the future we'll be seen.”","questions":[{"q":"According to Paragraph 1, museums are faced with difficulties in ______.","options":["A. maintaining their plastic items","B. obtaining durable plastic artifacts","C. handling outdated plastic exhibits","D. classifying their plastic collections"],"k":0,"ans":"选 A。解析：细节题。第一段指出塑料材料会开裂、渗出添加剂、熔成污泥，All of which creates huge headaches for institutions, such as museums, trying to preserve culturally important objects。可见博物馆的难题在于维护其塑料藏品，A 项中 maintaining 对应 preserve，故选 A。"},{"q":"Van Oosten believes that certain plastic objects are ______.","options":["A. immune to decay","B. improperly shaped","C. inherently flawed","D. complex in structure"],"k":2,"ans":"选 C。解析：细节题。第二段指出某些藏品特别脆弱，是因为一些塑料艺术先驱 didn't always know how to mix ingredients properly，并以“烤蛋糕配料不准就会失败”作比，称其“已经是一颗定时炸弹”。这说明作品本身先天存在缺陷，故选 C。"},{"q":"Museums stopped exhibiting some of Gilardi's artworks to ______.","options":["A. keep them from hurting visitors","B. duplicate them for future display","C. have their ingredients analyzed","D. prevent them from further damage"],"k":3,"ans":"选 D。解析：细节题。第四段指出聚氨酯泡沫 especially vulnerable to light damage，到 20 世纪 90 年代中期作品已开裂破碎，因此 Museums locked some of them away in the dark。把作品锁在暗处正是为了避免进一步（光）损害，故选 D。"},{"q":"The author thinks that preservation of plastics is ______.","options":["A. costly","B. unworthy","C. unpopular","D. challenging"],"k":3,"ans":"选 D。解析：细节题。末段首句：Despite success stories like van Oosten's, preservation of plastics will likely get harder。D 项 challenging 是对 get harder 的同义替换，故选 D。"},{"q":"In Ferreira's opinion, preservation of plastic artifacts ______.","options":["A. will inspire future scientific research","B. has profound historical significance","C. will help us separate the material ages","D. has an impact on today's cultural life"],"k":1,"ans":"选 B。解析：细节题。末段引用 Ferreira 的话：考古学家正是通过考察博物馆藏品才界定了石器时代、铁器时代等人类物质时代；如今我们身处塑料时代，“今天决定收藏什么、保存什么……将极大影响未来人们如何看待我们”。可见保存塑料文物具有深远的历史意义，故选 B。"}]},{"year":2023,"text":"Text 1","src":"2023 考研英语一 阅读理解 Text 1","title":"美国学校气候变化教育之争","passage":"The weather in Texas may have cooled since the recent extreme heat, but the temperature will be high at the State Board of Education meeting in Austin this month as officials debate how climate change is taught in Texas schools.\nPat Hardy, a conservative member of the board who sympathises with the views of the energy sector, is resisting proposed changes to science standards for pre-teen pupils. These would emphasise the primacy of human activity in recent climate change and encourage discussion of mitigation measures.\nMost scientists and independent experts sharply dispute her views. “They casually dismiss the career work of scholars and scientists as just another misguided opinion,” says Dan Quinn, senior communications strategist at the Texas Freedom Network, a non-profit group that monitors public education. “What millions of Texas kids learn in their public schools is determined too often by the political ideology of partisan board members, rather than facts and sound scholarship.”\nSuch debates reflect fierce discussions across the US and around the world, as researchers, policymakers, teachers and students step up demands for a greater focus on teaching about the facts of climate change in schools.\nA study last year by the National Center for Science Education, a non-profit group of scientists and teachers, looking at how state public schools across the country address climate change in science classes, gave barely half of US states a grade B+ or higher. Among the 10 worst performers were some of the most populous states, including Texas, which was given the lowest grade (F) and has a disproportionate influence because its textbooks are widely sold elsewhere.\nGlenn Branch, the centre's deputy director, cautions that setting state-level science standards is only one limited benchmark in a country that decentralises decisions to local school boards. Even if a state is considered a high performer in its science standards, “that does not mean it will be taught”, he says.\nAnother issue is that, while climate change is well integrated into some subjects and at some ages — such as earth and space sciences in high schools — it is not as well represented in curricula for younger children and in subjects that are more widely taught, such as biology and chemistry. It is also less prominent in many social studies courses.\nBranch points out that, even if a growing number of official guidelines and textbooks reflect scientific consensus on climate change, unofficial educational materials that convey more slanted perspectives are being distributed to teachers. They include materials sponsored by libertarian think-tanks and energy industry associations.","questions":[{"q":"In Paragraph 1, the weather in Texas is mentioned to ______.","options":["A. forecast a policy shift in Texas schools","B. stress the consequences of climate change","C. indicate the atmosphere at the board meeting","D. draw the public's attention to energy shortages"],"k":2,"ans":"选 C。解析：例证题。首段先说得州天气已转凉，随后以 but 转折指出 the temperature will be high at the State Board of Education meeting。作者利用 temperature 的双关（温度／激烈程度），以天气转凉反衬会议气氛热烈，C 项 atmosphere 正是对该比喻义的合理解读，故选 C。"},{"q":"What does Quinn think of Hardy?","options":["A. She exaggerates the existing panic.","B. She denies the value of scientific work.","C. She shows no concern for pre-teens.","D. She expresses self-contradictory views."],"k":1,"ans":"选 B。解析：细节题。第三段 Quinn 说 They casually dismiss the career work of scholars and scientists as just another misguided opinion（他们随意地把学者和科学家的毕生工作贬为又一种被误导的观点）。可见 Quinn 认为 Hardy 否定科学研究的价值，故选 B。"},{"q":"The study mentioned in Paragraph 5 shows that ______.","options":["A. climate education is insufficient at state public schools","B. policymakers have little drive for science education","C. Texas is reluctant to rewrite its science textbooks","D. environmental teaching in some states lacks supervision"],"k":0,"ans":"选 A。解析：细节题。第五段研究显示，全美仅有勉强一半的州在科学课中处理气候变化问题上获得 B+ 或更高评级，得州更是垫底（F）。这说明州立公立学校的气候教育普遍不足，故选 A。"},{"q":"According to Branch, state-level science standards in the US ______.","options":["A. call for regular revision","B. require urgent application","C. have limited influence","D. cater to local needs"],"k":2,"ans":"选 C。解析：细节题。第六段 Branch 指出，在一个把决策权下放给地方学区委员会的国家里，制定州级科学标准 is only one limited benchmark，且“即便标准很高，也不意味着真的会去教”。可见其影响有限，故选 C。"},{"q":"It is implied in the last paragraph that climate change teaching in some schools ______.","options":["A. agrees to major public demands","B. reflects teachers' personal biases","C. may misrepresent the energy sector","D. can be swayed by external forces"],"k":3,"ans":"选 D。解析：推断题。末段指出，尽管官方指南和教材日益反映科学共识，但带有偏颇观点的非官方教材正被分发给教师，其中包括由自由意志主义智库和能源行业协会赞助的材料。可见学校的气候变化教学可能受到外部势力左右，故选 D。"}]},{"year":2024,"text":"Text 1","src":"2024 考研英语一 阅读理解 Text 1","title":"一枚钉子的经济学：廉价技术改变世界","passage":"Nearly 2,000 years ago, as the Romans began to pull out of Scotland, they left behind a curious treasure: 10 tons of nails, nearly a million of the things. The nail hoard was discovered in 1960 in a four-metre-deep pit covered by two metres of gravel.\nWhy had the Romans buried a million nails? The likely explanation is that the withdrawal was rushed, and they didn't want the local Caledonians getting their hands on 10 tons of weapon-grade iron. The Romans buried the nails so deep that they would not be discovered for almost two millennia.\nLater civilisations would value the skilled blacksmith's labour in a nail even more than the raw material. As Roma Agrawal explains in her new delightful book Nuts and Bolts, early 17th-century Virginians would sometimes burn down their homes if they were planning to relocate. This was an attempt to recover the valuable nails, which could be reused after sifting the ashes. The idea that one might burn down an entire house just to reclaim the nails underlines how scarce, costly and valuable the simple-seeming technology was.\nThe price of nails fell by 90% between the late 1700s and mid-1900s, as economist Daniel Sichel points out in a research paper. According to Sichel, although the falling price of nails was driven partly by cheaper iron and cheaper energy, most of the credit goes to nail manufacturers who simply found more efficient ways to turn steel into nails.\nNails themselves have changed over the years, but Sichel studied them because they haven't changed much. Roman lamps and Roman chariots are very different from LED strips and sports cars, but Roman nails are still clearly nails. It would be absurd to try to track the changing price of sports cars since 1695, but to ask the same question of nails makes perfect sense.\nI make no apology for being obsessed by a particular feature of these objects: their price. I am an economist, after all. After writing two books about the history of inventions, one thing I've learnt is that while it is the enchantingly sophisticated technologies that get all the hype, it's the cheap technologies that change the world.\nThe Gutenberg printing press transformed civilisation not by changing the nature of writing but by changing its cost — and it would have achieved little without a parallel collapse in the price of surfaces to write on, thanks to an often-overlooked technology called paper. Solar panels had few niche uses until they became cheap; now they are transforming the global energy system.","questions":[{"q":"The Romans buried the nails probably for the sake of ______.","options":["A. saving them for future use","B. keeping them from rusting","C. letting them grow in value","D. hiding them from the locals"],"k":3,"ans":"选 D。解析：细节题。第二段自问自答：the withdrawal was rushed, and they didn't want the local Caledonians getting their hands on 10 tons of weapon-grade iron（撤退仓促，他们不想让当地的喀里多尼亚人拿到 10 吨武器级铁材）。可见埋钉是为了不让当地人得到，故选 D。"},{"q":"The example of early 17th-century Virginians is used to ______.","options":["A. highlight the thriftiness of early American colonists","B. illustrate the high status of blacksmiths in that period","C. contrast the attitudes of different civilisations towards nails","D. show the preciousness of nail-making technology at that time"],"k":3,"ans":"选 D。解析：例证题。该例的论点句是 Later civilisations would value the skilled blacksmith's labour in a nail even more than the raw material，段末又总结 underlines how scarce, costly and valuable the simple-seeming technology was。可见例子意在说明当时制钉技术之珍贵，故选 D。"},{"q":"What played the major role in lowering the price of nails after the late 1700s?","options":["A. Increased productivity","B. Wider use of new energies","C. Fiercer market competition","D. Reduced cost of raw materials"],"k":0,"ans":"选 A。解析：细节题。第四段指出，钉子降价虽部分源于更便宜的铁和能源，但 most of the credit goes to nail manufacturers who simply found more efficient ways to turn steel into nails。生产效率提高才是主因，故选 A。"},{"q":"It can be learned from Paragraph 5 that nails ______.","options":["A. have undergone many technological improvements","B. have remained basically the same since Roman times","C. are less studied than other everyday products","D. are one of the world's most significant inventions"],"k":1,"ans":"选 B。解析：推断题。第五段指出 Sichel 研究钉子正是因为 they haven't changed much，并说罗马的灯具和战车与今天的 LED 灯带、跑车大不相同，but Roman nails are still clearly nails。可见钉子自罗马时代以来基本未变，故选 B。"},{"q":"Which of the following best summarises the last two paragraphs?","options":["A. Cheap technologies bring about revolutionary change.","B. Technological innovation is integral to economic success.","C. Technology defines people's understanding of the world.","D. Sophisticated technologies develop from small inventions."],"k":0,"ans":"选 A。解析：主旨概括题。倒数第二段的核心句是 it's the cheap technologies that change the world；末段用古登堡印刷机（靠降低成本）与太阳能板（变便宜后才普及）加以印证。两段共同说明廉价技术带来革命性变革，故选 A。"}]}];

/* 英一翻译真题（每日 3 句，联网查找历年真题，点击查看标准答案） */
const EN_TRANSLATE_EXAM = [{"y":2023,"text":"AI can also be used to identify the lifestyle choices of customers regarding their hobbies, favourite celebrities and fashions to provide unique content in marketing messages put out through social media. Some believe that AI is negatively impacting on the marketer's role by reducing creativity and removing jobs, but they are aware that it is a way of reducing costs and creating new information. Algorithms that are used to simulate human interactions are creating many of these concerns, especially as no-one is quite sure what the outcomes of using AI to interact with customers will be. If customers are not willing to share data, AI will be starved of essential information and will not be able to function effectively or employ machine learning to improve its marketing content and communication. The non-intrusive delivery of the marketing messages in a way that is sensitive to the needs of the target customer is one of the critical challenges to the digital marketer.","zh":"人工智能还可以用来识别出消费者生活方式的选择，包括他们的爱好、最喜欢的名人和时尚，从而通过社交媒体发布的营销信息来提供独特的内容。一些人认为，人工智能通过减少创造力和工作机会对营销人员产生了负面影响，但他们也意识到，这是一种降低成本和创造新信息的方式。用于模拟人类互动的算法正在引发许多此类担忧，尤其是在没有人非常确定使用人工智能与客户互动的结果会是什么情况下。如果客户不愿意分享数据，人工智能将缺乏必要的信息，无法有效地发挥作用，也无法使用机器学习来改善其营销内容和传播。以一种对目标客户需求敏感的方式非侵入式地传递营销信息是数字营销人员面临的关键挑战之一。"},{"y":2022,"text":"It was also, and this is unknown even to many people well read about the period, a battle between those who made codes and those who broke them. It listed many documents in code that had been captured from the French army of Spain, and whose secrets had been revealed by the work of one George Scovell, an officer in British headquarters. he could not analyze carefully what this obscure officer may or may not have contributed to that great struggle between nations or indeed tell us anything much about the man himself. There may have been many spies and intelligence officers during the Napoleonic Wars, but it is usually extremely difficult to find the material they actually provided or worked on. Just as the code breaking has its wider relevance in the struggle for Spain, so his attempts to make his way up the promotion ladder speak volumes about British society.","zh":"即使是对许多好好研读过这段时期历史的人来说，他们也不知道这也是一场创造密码的人和破解密码的人之间的较量。它（书中）列出了许多从西班牙的法国军队那里缴获的密码文件，这些文件的秘密已经被英军指挥部的一位军官乔治·斯科维尔揭露了出来。他（阿曼）无法精细分析这位鲜为人知的军官是否对那场国家间的大规模战争起到作用，也无法确切地告诉我们更多有关他本人的任何事情。在拿破仑战争期间，可能有很多间谍和情报官员，但通常很难找到他们实际提供或研究过的资料。正如密码破译在争夺西班牙的斗争中有其更广泛的意义，他在晋升途径上的尝试也提供了很多关于英国社会的信息。"},{"y":2021,"text":"Those societies came out of the war with levels of enrollment that had been roughly constant at 3%-5% of the relevant age groups during the decades before the war. And the demand that rose in those societies of entry to higher education extended to groups and social classes that had not thought of attending a university before the war. In many countries of western Europe, the numbers of student in higher education doubled within five-year periods during the 1960s and doubled again in seven, eight or 10 years by the middle of the 1970s. and when the new staff are predominantly young men and women fresh from past graduate study, they largely define the norms of academic life in that faculty. High growth rates increased the chances for academic innovation, they also weakened the forms and process by which teachers and students are admitted into a community of scholars during periods of stability or slow growth.","zh":"战争结束后，这些社会的入学率在战前的几十年里一直保持在相关年龄段的3%-5%。在那些社会中，对接受高等教育的需求上升，延伸到了战前没有想过上大学的群体和社会阶层。在西欧许多国家，20世纪60年代接受高等教育的学生人数在5年内翻了一番，到70年代中期，在7年、8年或10年里又翻了一番。当新员工主要是刚从研究生学习中毕业的年轻男女时，他们在很大程度上定义了该学院学术生活的规范。高增长率增加了学术创新的机会，也削弱了在稳定或缓慢增长时期教师和学生在被接纳为学者群体时的形式和过程。"}];;
/* 新增：EN_TRANSLATIONS */
const EN_TRANSLATIONS = [{"src":"The Economist《经济学人》","title":"On lifelong learning（论终身学习）","text":"The most valuable skill of the coming decade may be the ability to learn new things quickly. Careers no longer follow a single track; the tools of today are the ruins of tomorrow. Those who treat education as a phase that ends with a diploma will find the ground shifting beneath them. The learners who thrive are not the ones who know the most, but the ones who can unlearn and relearn without shame. A mind kept flexible is worth more than a shelf of fixed expertise.","zh":"未来十年最宝贵的技能，或许就是快速学习新事物的能力。职业不再沿单一轨道前进；今天的工具，明天就成了废墟。把教育当作一纸文凭便告终的人，会发现脚下的土地正在移动。真正茁壮成长的学习者，不是知道得最多的人，而是能够不带羞耻地忘却与重新学习的人。保持灵活的心智，胜过一架固定的专业藏书。"},{"src":"The Guardian《卫报》","title":"On failure（论失败）","text":"Failure is not the opposite of success; it is part of its texture. Every competent person you admire has a graveyard of abandoned projects behind them. What separates the resilient from the defeated is not the absence of setbacks but the interpretation of them. The defeated read a stumble as a verdict; the resilient read it as data. One closes the book, the other turns the page.","zh":"失败不是成功的对立面，而是成功质地的一部分。你钦佩的每一个能人，背后都有一座弃项目的坟场。坚韧者与溃败者的区别，不在于是否遭遇挫折，而在于如何解读挫折。溃败者把踉跄当作定论；坚韧者把它当作数据。一个合上书，另一个翻过页。"},{"src":"Scientific American《科学美国人》","title":"On curiosity（论好奇心）","text":"Curiosity is the engine of understanding. It is the discomfort of not knowing that pushes a mind to look once more, to test, to question the obvious. Societies that punish the wrong question stagnate; those that reward the brave one leap forward. To stay curious is to accept that you are permanently unfinished—and to find, in that incompleteness, a kind of freedom.","zh":"好奇心是理解的引擎。正是“不知”带来的不安，推动心智再看一眼、再试一次、去质疑显而易见之事。惩罚错误问题的社会会停滞；奖赏勇敢问题的社会会跃迁。保持好奇，就是接受自己永远未完成——并在这种未完成中，找到一种自由。"},{"src":"The Atlantic《大西洋月刊》","title":"On solitude（论独处）","text":"Solitude is not loneliness. It is the deliberate withdrawal that lets a person meet their own thoughts without the noise of others. In constant company we borrow our opinions; in solitude we might finally form our own. The skill is scarce because it is uncomfortable—silence reveals what distraction hides. Yet those who learn it gain a companion who never leaves: themselves.","zh":"独处不是孤独。它是一种刻意的退避，让人得以在无人喧哗中遇见自己的思想。在不断的陪伴中我们借用他人的意见；在独处中我们或许才终于形成自己的意见。这项技能稀缺，因为它令人不适——沉默会揭露分心所掩盖的东西。然而习得它的人，收获了一位永不离去的同伴：自己。"},{"src":"The Washington Post《华盛顿邮报》","title":"On patience（论耐心）","text":"Patience is not passive waiting; it is active tending. The gardener waters what will not sprout this week, trusting the season. So it is with any worthy aim: the work that matters compounds quietly, invisible until the curve bends upward. To demand instant proof is to abandon the field before the harvest. The patient builder lays a foundation others cannot see and is mocked for it—until the structure stands.","zh":"耐心不是被动等待，而是积极的照料。园丁浇灌本周不会发芽的种子，信任季节。任何值得的目标亦如此：要紧的努力悄然复利，在曲线上扬前无人可见。要求即时证明，等于在收获前弃田而去。耐心的建造者打下他人看不见的地基，并因此被嘲笑——直到建筑矗立。"},{"src":"Nature《自然》","title":"On evidence（论证据）","text":"Evidence is the quiet authority that outlasts opinion. A claim dressed in confidence can sway a room, but only the claim tested by observation survives the morning. Science is, at heart, a habit of humility: a willingness to let the world correct you. We mistake certainty for strength, yet the stronger mind is the one that says, when the data disagree, 'I was wrong'—and means it.","zh":"证据是一种静默的权威，比意见更持久。披着自信外衣的说法能 sway 一室，但唯有经观察检验的说法能熬到天明。科学本质上是一种谦逊的习惯：愿意让世界纠正你。我们误把确信当力量，然而更强健的心智，是在数据与己相左时说“我错了”且发自内心的人。"},{"src":"Bloomberg Businessweek","title":"On craft（论匠心）","text":"Craft is the refusal to be merely adequate. It shows in the detail no customer is asked to notice: the clean seam, the honest label, the function that works on the tenth use as on the first. In a market that rewards speed, craft is a quiet rebellion. It costs more time than the competition allows, and it is precisely that cost which makes the result worth keeping.","zh":"匠心，是拒绝仅仅“够好”。它显现在无人被要求留意的细节里：干净的接缝、诚实的标签、第十次使用仍如初次般可靠的功能。在一个嘉奖速度的市场里，匠心是一场静默的反叛。它耗费的时光超出竞争所允，而恰恰是这份耗费，让成果值得留存。"},{"src":"The Christian Science Monitor","title":"On community（论共同体）","text":"No one thrives alone for long. A community is not a crowd but a web of small obligations—a borrowed cup, a returned favor, a door held open. These trivial acts accumulate into trust, and trust is the currency of cooperation. Places that lose their commons lose more than space; they lose the quiet insurance that someone will notice if you disappear.","zh":"没有人能长久地独自茁壮。共同体不是人群，而是一张由微小义务织成的网——一只借出的杯子、一次回报的恩惠、一扇为人扶住的门。这些琐碎之举积累成信任，而信任是合作的货币。失去公共空间的地方，失去的不只是场地；它们失去了“若你消失会有人察觉”这份静默的保障。"},{"src":"The Economist《经济学人》","title":"On change（论改变）","text":"Change is easiest when it is small and often. The system that waits for a grand overhaul rarely begins; the one that improves by a percent each week is unrecognizable a year later. Momentum hides in routine. A habit of tiny corrections beats a campaign of dramatic resolutions, because the first survives contact with ordinary life and the second dissolves in it.","zh":"改变在细小而频繁时最为容易。等待大刀阔斧革新的系统很少真正启动；而每周改善百分之一者，一年之后已面目全非。动量藏于日常。微小修正的习惯，胜过雄心勃勃的决心运动，因为前者能在庸常生活中存活，后者会在其中消散。"},{"src":"The Guardian《卫报》","title":"On words（论言语）","text":"Words are tools that shape thought. The language we lack, we cannot easily think; the distinctions we draw, we can act upon. To enrich vocabulary is not pedantry but liberation—it hands the mind finer instruments. A person with many words for a feeling can navigate it; one with few is swept by it. Precision in speech is, in the end, kindness to the listener and clarity to the self.","zh":"言语是塑造思想的工具。我们缺失的语言，便难以思考；我们做出的区分，方能据以行动。丰富词汇不是迂腐，而是解放——它把更精细的器具交到心智手中。对一个感受拥有许多词汇的人，能驾驭它；词汇稀少的人，则被它卷走。言语的精确，归根到底是给听者的善意，也是给自己的清明。"},{"src":"Scientific American《科学美国人》","title":"On uncertainty（论不确定）","text":"Uncertainty is not an error in the system; it is the system. The future is open, and pretending otherwise is a comfort that misleads. The skilled navigator does not demand a clear map but learns to sail by probabilities, adjusting the sail as the wind shifts. To live well with uncertainty is not to fear it less but to plan with it—building options, not bets, and keeping the door open for surprise.","zh":"不确定不是系统的错误，系统本身就是如此。未来是开放的，假装否则只是一种误导人的安慰。熟练的航行者不要求清晰的海图，而是学会按概率航行，随风转帆。与不确定好好共处，不是减少恐惧，而是与之共谋——构建选项而非下注，为意外留一扇门。"},{"src":"The Atlantic《大西洋月刊》","title":"On attention（论专注）","text":"Attention is the rarest form of generosity. To listen, truly, is to give another person your undivided now—a gift scarce in a divided age. We mistake multitasking for productivity, yet the mind that splits seldom deepens. The work that matters—a proof, a sentence, a friendship—demands a single beam, held steady. To focus is to say, to the world and to yourself, that this, here, is worth the whole of you.","zh":"专注是最稀罕的慷慨。真正的倾听，是把你全然的“此刻”献给另一个人——在分裂的时代里，这是一份稀缺的礼物。我们误把多任务当高效，然而分裂的心智很少深入。要紧的工作——一个证明、一句话、一段友谊——需要一束稳定的光。专注，就是对世界也对自己说：此情此景，值得你整个人的投入。"}];
/* 新增：EN_ZHENTI */
const EN_ZHENTI = [{"y":2024,"t":"图画作文：手机使用与志愿服务（碎片化时间的使用）","essay":"As is vividly depicted in the drawing, people of different ages are all staring at their phones, yet one young man puts his aside to help others, which conveys a thought-provoking message about how we spend our fragmented time.\n\nUndeniably, smartphones have made information and connection easier than ever. However, over-reliance on them reduces our ability to engage with the real world and with other people. The drawing suggests that the wisest use of technology is not to escape life but to make room for genuine service. Volunteering, even in small acts, rebuilds the face-to-face bonds that screens tend to thin.\n\nIn conclusion, we should treat the phone as a tool rather than a master. Only by balancing digital convenience with real-world kindness can we expect a warmer and more connected society."},{"y":2023,"t":"图画作文：大学生体育锻炼","essay":"The cartoon presents a group of college students jogging and playing sports, with a caption encouraging regular exercise. Simple as it is, the picture highlights a truth easily forgotten under academic pressure: a sound body is the foundation of everything else.\n\nMany students sacrifice sleep and exercise to study, yet research shows that moderate physical activity improves memory and mood. Exercise is not a rival of learning but its ally. Universities should therefore provide more accessible sports facilities and, more importantly, a culture that honors balance.\n\nTo sum up, physical fitness deserves a fixed place in every student's schedule. Only when we treat the body as carefully as the transcript can we truly thrive."},{"y":2022,"t":"图画作文：毕业后的多元选择","essay":"The drawing shows a graduate standing at a crossroads, facing diverse paths such as further study, employment, and entrepreneurship. It reflects a realistic dilemma of modern youth: there is no single 'right' route.\n\nIn the past, a stable job was the default. Today, choices multiply, and with them, anxiety. Yet multiplicity is also freedom. What matters is not which path is conventionally safest, but which aligns with one's genuine interest and capacity. A wrong turn is not fatal if one keeps learning.\n\nIn conclusion, young people should make decisions with courage and self-knowledge. Rather than fearing the unknown, we can view every choice as a beginning rather than an end."},{"y":2021,"t":"图画作文：坚持与放弃（爬山）","essay":"As the cartoon reveals, two climbers face a steep slope; one gives up while the other persists and reaches the top. The contrast delivers a plain but powerful lesson: perseverance, not talent, often decides the outcome.\n\nIn an age that celebrates quick success, many quit at the first difficulty. Yet most worthwhile goals demand sustained effort that temporary frustration cannot justify abandoning. The climber who continues proves that the view at the summit belongs to those who refuse to stop.\n\nTherefore, when obstacles appear, we should remind ourselves why we started. Only through persistence can ordinary effort be transformed into extraordinary result."},{"y":2020,"t":"图画作文：做好准备（抓住机会）","essay":"The picture portrays a man who, having prepared thoroughly, confidently catches the flying opportunity, while an unprepared one misses it. It tells us that opportunity favors the ready, not the merely hopeful.\n\nToo often we envy others' luck while ignoring their long preparation. In study and career alike, success is rarely sudden; it is the visible tip of invisible practice. To wait passively for a chance is to waste it; to prepare is to create it.\n\nIn short, we should invest in capability before the moment arrives. Only by being prepared can we turn a fleeting opportunity into lasting achievement."},{"y":2019,"t":"图画作文：途中（坚持的意义）","essay":"The cartoon shows a traveler resting midway, tempted to stop, with the hint that the destination is still far. It echoes an old theme: the value of a journey lies not in arrival alone but in the perseverance along the way.\n\nPeople often start with enthusiasm and lose it when progress slows. However, real growth happens in the long middle stretch that tests patience. Quitting midway wastes not only past effort but the self-belief built from it.\n\nTo conclude, we should learn to endure the ordinary middle. Only those who keep moving, step by step, eventually reach where they intend to be."},{"y":2018,"t":"图画作文：选课（选择与主动）","essay":"The drawing depicts students choosing courses according to their interests rather than following the crowd. It suggests that taking initiative in learning shapes not only a schedule but a person.\n\nIn a world of ready-made plans, many accept defaults without question. Yet education is most valuable when it is self-directed. Choosing what to learn trains judgment and responsibility, skills far beyond any single subject.\n\nIn conclusion, students should approach their studies with intention. Rather than drifting with the tide, we benefit most by making conscious, self-owned choices."},{"y":2017,"t":"图画作文：有书与读书（知识积累）","essay":"The cartoon contrasts a shelf full of unread books with a person who reads a little every day. It reminds us that owning knowledge is not the same as gaining it; what counts is consistent reading.\n\nMany people collect courses and books as a kind of security, yet unopened pages teach nothing. Understanding grows through the humble, repeated act of reading and reflecting, not through possession.\n\nTherefore, we should cultivate a daily reading habit. Only by turning accumulation into actual study can knowledge truly become part of us."},{"y":2016,"t":"图画作文：榜样胜过说教（家庭教育）","essay":"The picture shows a parent telling a child to study while the parent plays on the phone, implying that demands without example seldom work. It points to a core truth of education: behavior teaches louder than words.\n\nChildren learn less from instructions than from observed models. A parent who reads, exercises, and treats others well provides a living lesson no lecture can match. Hypocrisy, even unintended, quietly undermines authority.\n\nIn short, to educate a child, one should first educate oneself. Only by becoming the example can parents guide with genuine influence."},{"y":2015,"t":"图画作文：手机时代的聚会（网络的近与远）","essay":"The cartoon shows a group at dinner, each absorbed in a phone, physically together but mentally apart. It satirizes how digital connection can coexist with real-distance.\n\nTechnology promises closeness, yet excessive use can hollow out presence. We accumulate online friends while neglecting the person beside us. The paradox is that the more we connect virtually, the more we may drift socially.\n\nTo conclude, we should put devices aside at key moments. Only by offering full attention can we keep relationships warm in an age of constant connection."},{"y":2014,"t":"图画作文：相携（关爱老人）","essay":"The drawing portrays a young parent holding a child's hand on one side and an elderly parent's on the other, conveying the virtue of filial care across generations.\n\nAs societies age, the care of the elderly becomes a shared duty, not a private burden. Supporting aging parents is not only gratitude for past devotion but the moral foundation of a civilized community.\n\nIn conclusion, we should honor and accompany the old with action, not words. Only when the young and the old walk hand in hand can a society call itself truly humane."},{"y":2013,"t":"图画作文：选择（人生哲理）","essay":"The cartoon presents a person choosing between two roads, suggesting that life is a series of choices that define who we become. There is rarely a perfect option, only a committed one.\n\nIndecision often costs more than a wrong turn, because it freezes growth. Once a choice is made with care, energy should go to execution rather than regret. Responsibility, not luck, shapes a life.\n\nTherefore, we should choose deliberately and then commit fully. Only by owning our choices can we build a life of meaning rather than one of hesitation."},{"y":2012,"t":"图画作文：乐观心态","essay":"The picture shows a man smiling at a half-empty glass, while another frowns, illustrating that the same fact can be met with optimism or pessimism. Attitude, not circumstance, often decides our experience.\n\nLife inevitably brings setbacks; what differs is interpretation. An optimistic mind treats difficulty as temporary and solvable, which in turn sustains effort. Pessimism, by contrast, drains the will to act.\n\nIn conclusion, we should cultivate an optimistic outlook. Only by facing reality with hope can we keep moving when conditions are far from ideal."},{"y":2011,"t":"图画作文：旅途之“余”（环境保护）","essay":"The cartoon depicts travelers leaving litter 'beside' the path, revealing that pollution often hides just out of sight. It warns us that environmental harm is frequently the leftover of careless convenience.\n\nDevelopment matters, yet it must not discard nature as waste. Small daily choices—refusing litter, saving resources—accumulate into a livable or ruined environment. The 'remainder' we ignore today becomes tomorrow's crisis.\n\nTo sum up, we should extend responsibility beyond what is visible. Only by caring for the unnoticed can we protect the world we all share."},{"y":2010,"t":"图画作文：文化“火锅”（文化融合）","essay":"The drawing serves a 'hotpot' of cultures—Western philosophy, Chinese kung fu, and global symbols mixed together—implying that cultural exchange enriches rather than dilutes identity.\n\nIn an interconnected world, cultures meet constantly. Fear of mixing is outdated; wise absorption strengthens a culture by adding perspective. The key is openness with discernment, not blind imitation.\n\nIn conclusion, we should embrace cultural dialogue. Only by tasting and blending the world's flavors can our own tradition stay vivid and alive."},{"y":2009,"t":"图画作文：网络的近与远（重考）","essay":"The cartoon shows family members each facing a screen, close in distance yet far in feeling, echoing the paradox of the internet age. Connection is abundant, yet presence is scarce.\n\nThe network extends our reach but can shrink our attention to those near us. We must remember that relationships are built in shared moments, not in parallel scrolling. Technology should serve bonds, not replace them.\n\nTherefore, we should balance online and offline life. Only by being truly present can we keep the warmth that machines cannot supply."}];


